begin;
do $$declare u uuid:='eded6000-0000-4000-8000-000000000001';pid uuid;actor uuid;v integer;r jsonb;stamp timestamptz;s uuid;c uuid;preview jsonb;
begin
 select id into pid from player_identities where account_user_id=u;select id into actor from staff_users where email='padelleria-admin@example.invalid';if pid is null or actor is null then raise exception 'fixtures required';end if;
 select version into v from player_profiles where player_identity_id=pid;
 r:=player_profile_write_user(u,v,'{"descriptive_level":"avanzato","preferred_clubs":["Manta"],"available_other_clubs":false,"preferred_match_types":["any"],"available_last_minute":null,"availability":[{"weekday":2,"time_window":"evening"}]}'::jsonb);if (r->>'version')::integer<>v+1 then raise exception 'user version failed';end if;
 begin perform player_profile_write_user(u,v,'{"descriptive_level":null,"preferred_clubs":[],"available_other_clubs":null,"preferred_match_types":[],"available_last_minute":null,"availability":[]}'::jsonb);raise exception 'stale accepted';exception when others then if sqlerrm not like '%STALE_PROFILE%' then raise;end if;end;
 begin perform player_profile_write_user(u,v+1,'{"descriptive_level":null,"preferred_clubs":[],"available_other_clubs":null,"preferred_match_types":["any","mixed"],"available_last_minute":null,"availability":[]}'::jsonb);raise exception 'any combination accepted';exception when others then if sqlerrm not like '%MATCH_TYPES_INVALID%' then raise;end if;end;
 r:=player_profile_write_admin(actor,pid,v+1,'{"descriptive_level":"intermedio","preferred_clubs":["Revello"],"available_other_clubs":true,"preferred_match_types":["mixed"],"available_last_minute":true,"availability":[{"weekday":1,"time_window":"morning"}]}'::jsonb,3.5,'Nota SQL locale');select movi_level_updated_at into stamp from player_admin_profiles where player_identity_id=pid;
 perform player_profile_write_admin(actor,pid,(r->>'version')::integer,'{"descriptive_level":"intermedio","preferred_clubs":["Revello"],"available_other_clubs":true,"preferred_match_types":["mixed"],"available_last_minute":true,"availability":[]}'::jsonb,3.5,'Nota aggiornata');if (select movi_level_updated_at from player_admin_profiles where player_identity_id=pid) is distinct from stamp then raise exception 'level timestamp changed without value change';end if;
 if has_table_privilege('anon','public.player_profiles','select') or has_table_privilege('authenticated','public.player_admin_profiles','select') then raise exception 'browser grant exposed';end if;
 insert into player_identities(full_name,normalized_phone,gender) values('Profilo Merge Sorgente','+393470009991','M') returning id into s;insert into player_identities(full_name,normalized_phone,gender) values('Profilo Merge Destinazione','+393470009992','M') returning id into c;
 insert into player_profiles(player_identity_id,descriptive_level,preferred_clubs,preferred_match_types,updated_by_admin_id) values(s,'avanzato',array['Manta'],array['male'],actor);
 update player_identities set normalized_phone='+393470009992' where id=s;
 if not exists(select 1 from player_identity_cases where case_type='identity_data_conflict' and source_kind='admin_identity' and s=any(player_ids) and c=any(player_ids)) then raise exception 'phone conflict case missing';end if;
 preview:=player_identity_merge_preview(s,c);perform player_identity_merge(s,c,preview->>'fingerprint',actor);
 if not exists(select 1 from player_profiles where player_identity_id=c and descriptive_level='avanzato') then raise exception 'profile not copied to canonical identity';end if;
end $$;
rollback;
select 'PLAYER PROFILE SQL PASS' result;
